func TestE2MulMaxed(t *testing.T) {
	// let's pick a and b, with maxed A0 and A1
	var a, b E2
	qMinusOne := fr.Element{2013265921}
	qMinusOne[0]--

	a.A0 = qMinusOne
	a.A1 = qMinusOne
	b.A0 = qMinusOne
	b.A1 = qMinusOne

	var c, d E2
	d.Inverse(&b)
	c.Set(&a)
	c.Mul(&c, &b).Mul(&c, &d)
	if !c.Equal(&a) {
		t.Fatal("mul with max fr failed")
	}
}

func TestE2Ops(t *testing.T) {

	t.Parallel()
	parameters := gopter.DefaultTestParameters()
	if testing.Short() {
		parameters.MinSuccessfulTests = nbFuzzShort
	} else {
		parameters.MinSuccessfulTests = nbFuzz
	}

	properties := gopter.NewProperties(parameters)

	genA := genE2()
	genB := genE2()
	genfr := genFr()

	properties.Property("[babybear] sub & add should leave an element invariant", prop.ForAll(
		func(a, b E2) bool {
			var c E2
			c.Set(&a)
			c.Add(&c, &b).Sub(&c, &b)
			return c.Equal(&a)
		},
		genA,
		genB,
	))

	properties.Property("[babybear] mul & inverse should leave an element invariant", prop.ForAll(
		func(a, b E2) bool {
			var c, d E2
			d.Inverse(&b)
			c.Set(&a)
			c.Mul(&c, &b).Mul(&c, &d)
			return c.Equal(&a)
		},
		genA,
		genB,
	))

	properties.Property("[babybear] BatchInvertE2 should output the same result as Inverse", prop.ForAll(
		func(a, b, c E2) bool {

			batch := BatchInvertE2([]E2{a, b, c})
			a.Inverse(&a)
			b.Inverse(&b)
			c.Inverse(&c)
			return a.Equal(&batch[0]) && b.Equal(&batch[1]) && c.Equal(&batch[2])
		},
		genA,
		genA,
		genA,
	))

	properties.Property("[babybear] inverse twice should leave an element invariant", prop.ForAll(
		func(a E2) bool {
			var b E2
			b.Inverse(&a).Inverse(&b)
			return a.Equal(&b)
		},
		genA,
	))

	properties.Property("[babybear] neg twice should leave an element invariant", prop.ForAll(
		func(a E2) bool {
			var b E2
			b.Neg(&a).Neg(&b)
			return a.Equal(&b)
		},
		genA,
	))

	properties.Property("[babybear] square and mul should output the same result", prop.ForAll(
		func(a E2) bool {
			var b, c E2
			b.Mul(&a, &a)
			c.Square(&a)
			return b.Equal(&c)
		},
		genA,
	))

	properties.Property("[babybear] MulByElement MulByElement inverse should leave an element invariant", prop.ForAll(
		func(a E2, b fr.Element) bool {
			var c E2
			var d fr.Element
			d.Inverse(&b)
			c.MulByElement(&a, &b).MulByElement(&c, &d)
			return c.Equal(&a)
		},
		genA,
		genfr,
	))

	properties.Property("[babybear] Double and mul by 2 should output the same result", prop.ForAll(
		func(a E2) bool {
			var b E2
			var c fr.Element
			c.SetUint64(2)
			b.Double(&a)
			a.MulByElement(&a, &c)
			return a.Equal(&b)
		},
		genA,
	))

	properties.Property("[babybear] a + pi(a), a-pi(a) should be real", prop.ForAll(
		func(a E2) bool {
			var b, c, d E2
			var e, f fr.Element
			b.Conjugate(&a)
			c.Add(&a, &b)
			d.Sub(&a, &b)
			e.Double(&a.A0)
			f.Double(&a.A1)
			return c.A1.IsZero() && d.A0.IsZero() && e.Equal(&c.A0) && f.Equal(&d.A1)
		},
		genA,
	))

	properties.Property("[babybear] Legendre on square should output 1", prop.ForAll(
		func(a E2) bool {
			var b E2
			b.Square(&a)
			c := b.Legendre()
			return c == 1
		},
		genA,
	))

	properties.Property("[babybear] square(sqrt) should leave an element invariant", prop.ForAll(
		func(a E2) bool {
			var b, c, d, e E2
			b.Square(&a)
			c.Sqrt(&b)
			d.Square(&c)
			e.Neg(&a)
			return (c.Equal(&a) || c.Equal(&e)) && d.Equal(&b)
		},
		genA,
	))

	// Regression test for the silent failure of E2.Sqrt on purely-real
	// inputs whose Fp coordinate is a non-residue. The Scott §6.3 formula
	// divides by 2·y0 at the end; for x = (a, 0) with a non-QR in Fp the
	// inner Fp.Sqrt returned 0 and the function fell through to 0/0,
	// producing (0, 0) regardless of the actual square root. The fix
	// special-cases x.A1 == 0 and looks for an E2 root of the form (0, b)
	// with β·b² = a.
	properties.Property("[babybear] square(sqrt) should be invariant for purely-real inputs", prop.ForAll(
		func(a fr.Element) bool {
			var x, root, sq E2
			x.A0.Set(&a)
			// (a, 0) is always an E2-square for a != 0: either a is QR in
			// Fp, or a/β is (since β is itself a non-residue).
			root.Sqrt(&x)
			sq.Square(&root)
			return sq.Equal(&x)
		},
		genFr(),
	))

	properties.Property("[babybear] neg(E2) == neg(E2.A0, E2.A1)", prop.ForAll(
		func(a E2) bool {
			var b, c E2
			b.Neg(&a)
			c.A0.Neg(&a.A0)
			c.A1.Neg(&a.A1)
			return c.Equal(&b)
		},
		genA,
	))

	properties.Property("[babybear] Cmp and LexicographicallyLargest should be consistent", prop.ForAll(
		func(a E2) bool {
			var negA E2
			negA.Neg(&a)
			cmpResult := a.Cmp(&negA)
			lResult := a.LexicographicallyLargest()
			if lResult && cmpResult == 1 {
				return true
			}
			if !lResult && cmpResult != 1 {
				return true
			}
			return false
		},
		genA,
	))

	properties.TestingRun(t, gopter.ConsoleReporter(false))

}

